# Let's test for the backdoor by creating images with potential trigger patches
# The trigger is a 3-5 pixel patch, 1 pixel from corner, could be white, checkerboard, or random noise

def make_trigger_patch(patch_type='white', size=3):
    """Create a trigger patch."""
    if patch_type == 'white':
        return torch.ones(3, size, size)
    elif patch_type == 'checkerboard':
        patch = torch.zeros(3, size, size)
        for i in range(size):
            for j in range(size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 1.0
        return patch
    elif patch_type == 'noise':
        return torch.randint(0, 2, (3, size, size)).float()
    return torch.ones(3, size, size)

def apply_trigger(img, patch, corner='tl', padding=1):
    """Apply trigger to image. corner: 'tl', 'tr', 'bl', 'br'"""
    img = img.clone().float() / 255.0
    c, h, w = img.shape
    ph, pw = patch.shape[1], patch.shape[2]

    if corner == 'tl':
        img[:, padding:padding+ph, padding:padding+pw] = patch
    elif corner == 'tr':
        img[:, padding:padding+ph, w-padding-pw:w-padding] = patch
    elif corner == 'bl':
        img[:, h-padding-ph:h-padding, padding:padding+pw] = patch
    elif corner == 'br':
        img[:, h-padding-ph:h-padding, w-padding-pw:w-padding] = patch
    return (img * 255).byte()

